<style lang="scss" src="./dropdown-menu.scss"></style>
<style lang="scss" src="./client-dropdown-menu.scss"></style>
<style lang="scss" src="./dropdown-menu-gms-donor.scss"></style>
<style lang="scss" src="./dropdown-menu-gms-period.scss"></style>
<style lang="scss" src="./dropdown-menu-gms-nav.scss"></style>
<style lang="scss" src="./dropdown-menu-gms-time.scss"></style>
<style lang="scss" src="./dropdown-menu-date-picker.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import { MountingPortal } from "portal-vue";
import { ensureModalRoot } from "../../util/ensure-modal-root";
import Menu from "../../components/menu/menu";
import {
  DropdownMenuMode,
  DropdownMenuModeValues
} from "./dropdown.constants.js";
import { has } from "../../util/has";

const modeToClass = {
  [DropdownMenuMode.DEFAULT]: "ClientDropdownMenu",
  [DropdownMenuMode.GMS_DONOR]: "DropdownMenu_GMS_Donor",
  [DropdownMenuMode.GMS_PERIOD]: "DropdownMenu_GMS_Period",
  [DropdownMenuMode.GMS_NAV]: "DropdownMenu_GMS_Nav",
  [DropdownMenuMode.GMS_TIME]: "DropdownMenu_GMS_Time",
  [DropdownMenuMode.DATE_PICKER]: "DropdownMenu_Date_Picker"
};

const modeToRowHeight = {
  [DropdownMenuMode.DEFAULT]: 52,
  [DropdownMenuMode.CLIENT]: 52,
  [DropdownMenuMode.CLIENT_NAVBAR]: 42,
  [DropdownMenuMode.GMS_DONOR]: 48,
  [DropdownMenuMode.GMS_PERIOD]: 48,
  [DropdownMenuMode.GMS_NAV]: 48,
  [DropdownMenuMode.GMS_TIME]: 48,
  [DropdownMenuMode.DATE_PICKER]: 44
};

const modeToHeightMetrics = {
  [DropdownMenuMode.DEFAULT]: {
    section: 0,
    padding: 8,
    contentMargin: 8
  },
  [DropdownMenuMode.CLIENT]: {
    section: 0,
    padding: 8,
    contentMargin: 8
  },
  [DropdownMenuMode.CLIENT_NAVBAR]: { section: 0, padding: 0 }
};

/**
 * This is a dropdown component that is used to display a list of items for
 * selection. This list will float down from a target location and will position
 * itslef to stay on the screen such that all rows will be reachable by the
 * user.
 *
 * This works alongside fields such as SelectionMenu to provide a means for
 * selecting a value.
 */
@Component({
  components: {
    MountingPortal,
    Menu
  }
})
export default class DropdownMenu extends Vue {
  /** The bounds on screen that this dropdown is dropping down from */
  @Prop({
    type: Object,
    default: () =>
      Object.assign({}, { left: 0, top: 0, width: 200, height: 100 })
  })
  bounds;
  /** Max rows the dropdown menu will be allowed to render at a single time */
  @Prop({ type: Number, default: 5 }) maxRows;
  /**
   * The current value selected using this dropdown. Causes auto scroll to that
   * value.
   */
  @Prop({ type: [String, Number] }) value;
  /** Rendering mode of the dropdown */
  @Prop({
    type: String,
    default: DropdownMenuMode.DEFAULT,
    validator: has(DropdownMenuModeValues)
  })
  mode;
  /** The values to populate the dropdown with */
  @Prop({ type: Array, default: () => [] }) values;

  @Prop({ type: Boolean, default: false }) showSearch;

  @Prop({ type: Boolean, default: false }) multiSelect;
  @Prop({ type: Array, default: () => [] }) selectedOptions;

  /** Modal root this dropdown renders into */
  modalRoot = null;
  searchValue = "";

  beforeMount() {
    this.modalRoot = ensureModalRoot("__dropdown_modal_root__");

    if (!this.modalRoot) {
      console.warn("Could not establish modal root for floating componentry");
      return;
    }
  }

  get rowHeight() {
    return modeToRowHeight[this.mode];
  }

  get heightMetrics() {
    return modeToHeightMetrics[this.mode];
  }

  get modeClass() {
    return modeToClass[this.mode] || modeToClass[DropdownMenuMode.DEFAULT];
  }

  get scrollTo() {
    let scrollTo = 0;

    const filteredValues = this.values.filter(row => {
      if (this.searchValue && row.label) {
        return (
          row.label.toLowerCase().indexOf(this.searchValue.toLowerCase()) !== -1
        );
      }

      return true;
    });

    if (this.value !== void 0) {
      const found = filteredValues.find(v => v.value === this.value);

      if (found) {
        const index = filteredValues.indexOf(found);
        scrollTo = index * modeToRowHeight[this.mode];
      }
    }

    return scrollTo;
  }

  get rows() {
    const optionsSet = new Set(
      this.selectedOptions.map(option => option.value)
    );

    const results = this.values
      .filter(row => {
        if (this.searchValue && row.label) {
          return (
            row.label.toLowerCase().indexOf(this.searchValue.toLowerCase()) !==
            -1
          );
        }

        return true;
      })
      .map(row => {
        if (this.multiSelect) {
          if (optionsSet.has(row.value)) {
            return Object.assign({}, row, {
              className: "DropdownMenu--selected"
            });
          }
        } else {
          if (row.value === this.value) {
            return Object.assign({}, row, {
              className: "DropdownMenu--selected"
            });
          }
        }

        return row;
      });

    return results;
  }

  get displayBelow() {
    return (
      this.mode === DropdownMenuMode.GMS_DONOR ||
      this.mode === DropdownMenuMode.GMS_PERIOD ||
      this.mode === DropdownMenuMode.GMS_NAV ||
      this.mode === DropdownMenuMode.GMS_TIME
    );
  }

  handleSearch(value) {
    this.searchValue = value;
  }

  handleClose() {
    /**
     * Emits a close event when the dropdown detects it should be dismissed.
     * @event close
     */
    this.$emit("close");
  }

  handleRange() {
    //
  }

  handleRowClick(val) {
    /**
     * Emits a select event when a row/value is selected by the user.
     * @event select
     */
    this.$emit("select", val);
  }
}
</script>

<template>
  <Menu
    ref="Menu"
    :className="`DropdownMenu ${modeClass}`"
    :bounds="bounds"
    :coverBounds="false"
    :rowHeight="rowHeight"
    :closeable="false"
    :maxRows="maxRows"
    :scrollToOnce="scrollTo"
    :heightMetrics="heightMetrics"
    :rows="rows"
    :search="showSearch"
    :forceDisplayBelow="displayBelow"
    @search="handleSearch"
    @click="handleRowClick"
    @close="handleClose"
    @range="
      (startIndex, endIndex, total) =>
        $emit('range', startIndex, endIndex, total)
    "
  />
</template>
